WITH kept_keys AS (SELECT city FROM stores EXCEPT DISTINCT SELECT city FROM stores WHERE store_name NOT LIKE 'D%'), verified AS (SELECT s.* FROM stores s INNER JOIN kept_keys k ON s.city = k.city) SELECT id, store_name, region, CASE WHEN store_name RLIKE '^(Siam Flagship|Riverside)$' THEN 'GROUP_B' WHEN store_name RLIKE '^(Downtown Express|Airport Kiosk)$' THEN 'OTHER_ZONE' ELSE 'CORE' END AS store_name_zone FROM verified ORDER BY id DESC NULLS LAST
